// План specs/billing-granted-plan.md, 2.2. Granted-текст на иврите.
// ПИШЕТ данные на проде: только «בדיקה», revokeIfAssigned до и в finally. Не @prod-safe.
import { test, expect } from '../../fixtures';
import { setLanguage, revokeIfAssigned } from '../admin-plans/plans-helpers';
import { REASON, UNTIL_DAYS, PROPAGATION_MS, grantedTextHe, heDate, assignPlan } from './granted-helpers';

test.describe.configure({ mode: 'serial' });

test.describe('Billing — granted plan seen by the user', () => {
  test('Granted plan text is shown in Hebrew with the Hebrew date and no trial wording #550e01db @desktop @writes', async ({ asUser }) => {
    test.setTimeout(300_000);
    const admin = await asUser('admin');
    const user = await asUser('user');
    await setLanguage(admin, 'en');
    await setLanguage(user, 'he');

    await revokeIfAssigned(admin, `${REASON} pre-clean`);

    try {
      await assignPlan(admin, 'Starter Tech');

      await user.goto('/BillingSubscription');
      const granted = user.getByText(grantedTextHe(heDate(UNTIL_DAYS)));
      await expect(granted).toBeVisible({ timeout: PROPAGATION_MS });
      await expect(granted.locator('xpath=..')).not.toContainText('ניסיון');
      await expect(user.getByText(/trial/i)).toHaveCount(0);
    } finally {
      await revokeIfAssigned(admin, `${REASON} cleanup`);
    }
  });
});
